<script setup lang="ts">
import type { PublicArticle } from '../../../../../packages/contracts/src/index';
const route=useRoute();
const variant=computed(()=>route.query.variant==='brief'?'brief':'standard');
const {data,error}=await useFetch<{data:PublicArticle}>(()=>`/api/v1/articles/${route.params.slug}`,{query:{variant}});
if(import.meta.server && error.value) setResponseStatus(useRequestEvent()!,error.value.statusCode||503);
const article=computed(()=>data.value?.data);
const ordinal=(id:string)=>article.value?.sources.find(s=>s.id===id)?.ordinal;
const used=(id:string)=>article.value?.blocks.some(b=>b.sourceIds.includes(id));
const returnTarget=(id:string)=>article.value?.blocks.find(b=>b.sourceIds.includes(id))?.id||'article-header';
const sourceUrl=(s:PublicArticle['sources'][number])=>s.locator?.validated?`${s.url}?t=${Math.floor(s.locator.startMs/1000)}`:s.url;
const date=(value:string|null)=>value?new Date(value).toLocaleString('en-GB',{timeZone:'UTC',dateStyle:'medium',timeStyle:'short'})+' UTC':'Date unavailable';
useHead({title:computed(()=>article.value?`${article.value.headline} — The Aggregator`:'Article unavailable')});
</script>
<template>
  <main id="main" class="shell article-page" tabindex="-1">
    <section v-if="error" class="article-column" role="alert"><h1>{{ error.statusCode===410?'Article withdrawn':'Article unavailable' }}</h1><p>{{ error.statusCode===410?'This version is suppressed pending review.':'The reading service could not return this article.' }}</p><NuxtLink to="/">Return to the edition</NuxtLink></section>
    <article v-else-if="article">
      <header class="article-opening"><h1>{{ article.headline }}</h1><EditorialMedia v-if="article.leadMedia" :media="article.leadMedia" priority /></header>
      <div class="article-column">
      <header id="article-header" class="article-intro"><p class="eyebrow">{{ article.topic }} / The evening edition</p><p v-if="article.correction" class="correction"><strong>Correction · Version {{ article.version }}</strong><br>{{ article.correction }} <a href="#history">Read history</a></p><p class="deck">{{ article.deck }}</p><p class="metadata">{{ article.disclosure }}</p><p class="metadata">Version {{ article.version }} · Published {{ date(article.publishedAt) }}<br>Evidence cutoff {{ date(article.cutoff) }}</p><ReadingControls :variant="variant" :source-count="article.sources.length" :evidence-target="article.claims.some(c=>c.id==='claim-3')?'#claim-3':'#evidence'" /><nav class="metadata" aria-label="Story context"><NuxtLink :to="{path:`/topics/${article.topic.toLowerCase()}`,query:{theme:route.query.theme}}">More from {{ article.topic }}</NuxtLink> · <a :href="article.claims.some(c=>c.id==='claim-3')?'#claim-3':'#evidence'">Inspect evidence</a></nav><StoryFormats :slug="article.slug" :version-id="article.versionId" /><SaveStory :article-id="article.id" />
      </header>
      <section v-for="block in article.blocks" :id="block.id" :key="block.id" class="article-block" tabindex="-1"><h2>{{ block.heading }}</h2><p>{{ block.text }} <span class="citations"><a v-for="id in block.sourceIds" :key="id" :href="`#source-${ordinal(id)}`" :aria-label="`Source ${ordinal(id)}, ${article.sources.find(s=>s.id===id)?.publisher}`">[{{ ordinal(id) }}]</a></span></p><a v-if="block.claimIds.includes('claim-3')" class="control control--secondary evidence-link" href="#claim-3"><span class="control-content"><ControlIcon name="evidence" />Inspect the disputed counts<ControlIcon name="arrow" /></span></a><EditorialMedia v-for="entry in article.inlineMedia.filter(m=>m.afterBlockIds.includes(block.id))" :key="entry.media.id" :media="entry.media" /></section>
      <section v-if="article.claims.some(c=>c.id==='claim-3')" id="claim-3" class="evidence-panel" tabindex="-1" aria-labelledby="evidence-title"><p class="eyebrow">Evidence inspection · disputed</p><h2 id="evidence-title">Two counts. Two different measures.</h2><p>Alderwick Ledger counted 18 people waiting. Quay Notebook counted 24 boardings over a longer window that included the return journey. These figures cannot establish one unique-passenger total.</p><p>Public excerpts are not licensed in this fixture. Exact original-item links remain below.</p><div class="evidence-actions"><a class="control control--secondary" href="#source-2">Source 2</a><a class="control control--secondary" href="#source-3">Source 3</a><a class="control control--quiet control--icon" :href="`#${variant==='brief'?'brief-2':'block-3'}`" aria-label="Return to disputed claim" title="Return to disputed claim"><ControlIcon name="back" /></a></div></section>
      <section v-if="!article.claims.some(c=>c.id==='claim-3')" id="evidence" class="evidence-panel" tabindex="-1" aria-labelledby="evidence-title"><h2 id="evidence-title">Inspect the evidence</h2><p>These are attributed fictional accounts, not independently established real-world findings. Original source text is not reproduced.</p><div v-for="claim in article.claims" :id="claim.id" :key="claim.id"><h3>{{ claim.proposition }}</h3><p class="metadata">{{ claim.status }}</p><a v-for="id in claim.sourceIds" :key="id" :href="`#source-${ordinal(id)}`">Source {{ ordinal(id) }} · </a></div></section><section id="sources" class="bibliography" aria-labelledby="sources-title" tabindex="-1"><h2 id="sources-title">Sources and evidence</h2><NuxtLink to="/methodology">Methodology and source transparency</NuxtLink><p class="metadata">All {{ article.sources.length }} version-wide evidence items. Example-domain links are fictional; no real reporting was retrieved.</p><ol><li v-for="source in article.sources" :id="`source-${source.ordinal}`" :key="source.id" class="source-entry" tabindex="-1"><h3>{{ source.title }}</h3><p>{{ source.publisher }} · {{ source.author||'Author unavailable' }}</p><p class="metadata">Published {{ date(source.publishedAt) }}<br>Availability checked {{ date(source.checkedAt) }}</p><p class="metadata">{{ source.kind }} · {{ source.role }} · {{ used(source.id)?'Cited in this view':'Used in the full article' }}</p><p v-if="source.availability==='unavailable'" class="correction">Original unavailable. Only permitted metadata is retained; no cached copy is offered.</p><a class="action-link" :href="sourceUrl(source)" rel="noreferrer">{{ source.locator?'Open fictional video at 01:12':'Open original' }} ↗ <span class="metadata">(example.com mock link)</span></a><br><a class="action-link" :href="`#${returnTarget(source.id)}`">Return to citation ↑</a></li></ol></section>
      <section id="history" tabindex="-1"><h2>Corrections and version history</h2><p>{{ article.correction||'No corrections in this fictional version.' }}</p><p class="metadata">Version {{ article.version }} · {{ date(article.publishedAt) }}</p></section>
      </div>
    </article>
  </main>
</template>

